//! PKCS#12 and PEM keystore loading.
//!
//! Supports both legacy PKCS#12 (3DES/RC2, via the `p12` crate) and modern
//! PKCS#12 (PBES2+PBKDF2+AES-256-CBC, as generated by DevEco Studio), via
//! the `pkcs12` + `pkcs5` + `pkcs8` RustCrypto crates.

use std::path::Path;
use std::time::SystemTime;

use crate::error::SignError;
use der::{Decode, Encode};
use x509_cert::Certificate;

/// A loaded signing key + certificate chain.
pub struct SigningKey {
    /// PKCS#8 DER-encoded private key.
    pub private_key_der: Vec<u8>,
    /// DER-encoded X.509 certificates, leaf first.
    pub cert_chain: Vec<Vec<u8>>,
}

impl SigningKey {
    /// Load from a PKCS#12 (.p12 / .pfx) file.
    ///
    /// Tries the modern PBES2/AES-256-CBC path first (DevEco Studio keys),
    /// then falls back to the legacy 3DES/RC2 path.
    ///
    /// `key_alias` is currently unused (neither parser filters by alias),
    /// but kept in the signature for API compatibility with the Java tool.
    pub fn from_pkcs12(
        p12_bytes: &[u8],
        store_password: &str,
        _key_alias: &str,
        key_password: &str,
    ) -> Result<Self, SignError> {
        // Try modern PBES2 path first (DevEco Studio / OpenSSL 3.x default).
        match Self::from_pkcs12_pbes2(p12_bytes, store_password, key_password) {
            Ok(k) => Ok(k),
            Err(e_modern) => {
                // Fall back to legacy p12 crate (3DES / RC2).
                Self::from_pkcs12_legacy(p12_bytes, key_password).map_err(|e_legacy| {
                    SignError::KeystoreParseError(format!(
                        "PKCS#12 parse failed (modern: {e_modern}; legacy: {e_legacy})"
                    ))
                })
            }
        }
    }

    /// Load the application certificate chain from hapsigner `appCertFile`.
    ///
    /// Java hapsigner reads this with
    /// `CertificateFactory.getInstance("X.509").generateCertificates(...)`,
    /// sorts the chain to leaf-first order, then validates the chain relation.
    pub fn cert_chain_from_file(path: &Path) -> Result<Vec<Vec<u8>>, SignError> {
        let bytes = fs_err::read(path)?;
        let mut certs = if Self::is_pem_certificate_file(&bytes) {
            Self::cert_chain_from_pem_bytes(&bytes)?
        } else {
            Self::cert_chain_from_der_bytes(&bytes)?
        };
        if certs.is_empty() {
            return Err(SignError::NoCertificate);
        }
        Self::sort_certificate_chain(&mut certs)?;
        Self::verify_certificate_chain(&certs)?;
        Ok(certs)
    }

    fn is_pem_certificate_file(bytes: &[u8]) -> bool {
        bytes
            .windows(b"-----BEGIN CERTIFICATE-----".len())
            .any(|window| window == b"-----BEGIN CERTIFICATE-----")
    }

    fn cert_chain_from_pem_bytes(bytes: &[u8]) -> Result<Vec<Vec<u8>>, SignError> {
        const BEGIN: &str = "-----BEGIN CERTIFICATE-----";
        const END: &str = "-----END CERTIFICATE-----";

        let text = std::str::from_utf8(bytes)
            .map_err(|e| SignError::PemError(format!("certificate file is not UTF-8 PEM: {e}")))?;
        let mut rest = text;
        let mut certs = Vec::new();

        while let Some(begin_index) = rest.find(BEGIN) {
            let after_begin = &rest[begin_index + BEGIN.len()..];
            let end_index = after_begin.find(END).ok_or_else(|| {
                SignError::PemError("certificate PEM block missing END marker".to_string())
            })?;
            let body = &after_begin[..end_index];
            let encoded = body.lines().map(str::trim).collect::<String>();
            let cert_der =
                base64_decode(&encoded).map_err(|e| SignError::PemError(format!("{e}")))?;
            Self::validate_certificate_der(&cert_der)?;
            certs.push(cert_der);
            rest = &after_begin[end_index + END.len()..];
        }

        Ok(certs)
    }

    fn cert_chain_from_der_bytes(bytes: &[u8]) -> Result<Vec<Vec<u8>>, SignError> {
        let mut certs = Vec::new();
        let mut remaining = bytes;
        while !remaining.is_empty() {
            let cert_len = Self::der_tlv_len(remaining)?;
            let cert_der = remaining[..cert_len].to_vec();
            Self::validate_certificate_der(&cert_der)?;
            certs.push(cert_der);
            remaining = &remaining[cert_len..];
        }
        Ok(certs)
    }

    fn der_tlv_len(bytes: &[u8]) -> Result<usize, SignError> {
        if bytes.len() < 2 || bytes[0] != 0x30 {
            return Err(SignError::DerError(
                "certificate DER must start with SEQUENCE".to_string(),
            ));
        }
        let length_byte = bytes[1];
        let (length_len, content_len) = if length_byte & 0x80 == 0 {
            (0usize, length_byte as usize)
        } else {
            let length_len = (length_byte & 0x7f) as usize;
            if length_len == 0 || length_len > 4 || bytes.len() < 2 + length_len {
                return Err(SignError::DerError(
                    "certificate DER has invalid length field".to_string(),
                ));
            }
            let mut content_len = 0usize;
            for byte in &bytes[2..2 + length_len] {
                content_len = (content_len << 8) | (*byte as usize);
            }
            (length_len, content_len)
        };
        let total_len = 2 + length_len + content_len;
        if total_len > bytes.len() {
            return Err(SignError::DerError(
                "certificate DER length exceeds input".to_string(),
            ));
        }
        Ok(total_len)
    }

    fn validate_certificate_der(cert_der: &[u8]) -> Result<(), SignError> {
        Certificate::from_der(cert_der)
            .map(|_| ())
            .map_err(|e| SignError::DerError(format!("certificate parse: {e}")))
    }

    fn sort_certificate_chain(certs: &mut [Vec<u8>]) -> Result<(), SignError> {
        if certs.len() <= 1 {
            return Ok(());
        }
        let size = certs.len();
        let last_subject = Self::certificate_subject_der(&certs[size - 1])?;
        let before_last_issuer = Self::certificate_issuer_der(&certs[size - 2])?;
        if last_subject != before_last_issuer {
            certs.reverse();
        }
        Ok(())
    }

    fn verify_certificate_chain(certs: &[Vec<u8>]) -> Result<(), SignError> {
        if certs.len() <= 1 {
            return Ok(());
        }

        let parsed = certs
            .iter()
            .map(|cert_der| {
                Certificate::from_der(cert_der)
                    .map_err(|e| SignError::DerError(format!("certificate parse: {e}")))
            })
            .collect::<Result<Vec<_>, _>>()?;

        for i in 1..parsed.len() {
            let child = &parsed[i - 1];
            let parent = &parsed[i];
            Self::verify_certificate_signature(child, parent)?;
            Self::check_certificate_validity(child)?;

            let child_issuer = child
                .tbs_certificate
                .issuer
                .to_der()
                .map_err(|e| SignError::DerError(format!("issuer encode: {e}")))?;
            let parent_subject = parent
                .tbs_certificate
                .subject
                .to_der()
                .map_err(|e| SignError::DerError(format!("subject encode: {e}")))?;
            if child_issuer != parent_subject {
                return Err(SignError::DerError(
                    "certificate chain issuer does not match parent subject".to_string(),
                ));
            }

            if i == parsed.len() - 1 {
                Self::check_certificate_validity(parent)?;
            }
        }
        Ok(())
    }

    fn check_certificate_validity(cert: &Certificate) -> Result<(), SignError> {
        let now = SystemTime::now();
        let validity = &cert.tbs_certificate.validity;
        let not_before = validity.not_before.to_system_time();
        let not_after = validity.not_after.to_system_time();
        if now < not_before {
            return Err(SignError::DerError(
                "certificate chain contains a certificate that is not yet valid".to_string(),
            ));
        }
        if now > not_after {
            return Err(SignError::DerError(
                "certificate chain contains an expired certificate".to_string(),
            ));
        }
        Ok(())
    }

    fn verify_certificate_signature(
        child: &Certificate,
        parent: &Certificate,
    ) -> Result<(), SignError> {
        let tbs_der = child
            .tbs_certificate
            .to_der()
            .map_err(|e| SignError::DerError(format!("TBS certificate encode: {e}")))?;
        let signature = child.signature.as_bytes().ok_or_else(|| {
            SignError::DerError("certificate signature has unused bits".to_string())
        })?;
        let signature_oid = child.signature_algorithm.oid.to_string();
        match signature_oid.as_str() {
            "1.2.840.10045.4.3.2" => {
                Self::verify_ecdsa_certificate_signature(parent, &tbs_der, signature, "SHA256")
            }
            "1.2.840.10045.4.3.3" => {
                Self::verify_ecdsa_certificate_signature(parent, &tbs_der, signature, "SHA384")
            }
            "1.2.840.10045.4.3.4" => {
                Self::verify_ecdsa_certificate_signature(parent, &tbs_der, signature, "SHA512")
            }
            "1.2.840.113549.1.1.11" => {
                Self::verify_rsa_pkcs1_sha256_certificate_signature(parent, &tbs_der, signature)
            }
            "1.2.840.113549.1.1.12" => {
                Self::verify_rsa_pkcs1_sha384_certificate_signature(parent, &tbs_der, signature)
            }
            "1.2.840.113549.1.1.13" => {
                Self::verify_rsa_pkcs1_sha512_certificate_signature(parent, &tbs_der, signature)
            }
            other => Err(SignError::DerError(format!(
                "unsupported certificate signature algorithm: {other}"
            ))),
        }
    }

    fn verify_ecdsa_certificate_signature(
        parent: &Certificate,
        tbs_der: &[u8],
        signature: &[u8],
        digest: &str,
    ) -> Result<(), SignError> {
        let public_key = parent
            .tbs_certificate
            .subject_public_key_info
            .subject_public_key
            .as_bytes()
            .ok_or_else(|| {
                SignError::DerError("parent EC public key has unused bits".to_string())
            })?;
        let algorithm = match (public_key.len(), digest) {
            (65, "SHA256") => &ring::signature::ECDSA_P256_SHA256_ASN1,
            (65, "SHA384") => &ring::signature::ECDSA_P256_SHA384_ASN1,
            (97, "SHA256") => &ring::signature::ECDSA_P384_SHA256_ASN1,
            (97, "SHA384") => &ring::signature::ECDSA_P384_SHA384_ASN1,
            (len, digest) => {
                return Err(SignError::DerError(format!(
                    "unsupported ECDSA certificate verification key length/digest: {len}/{digest}"
                )));
            }
        };
        let verifier = ring::signature::UnparsedPublicKey::new(algorithm, public_key);
        verifier.verify(tbs_der, signature).map_err(|_| {
            SignError::DerError("verify certificate chain signature failed".to_string())
        })
    }

    fn verify_rsa_pkcs1_sha256_certificate_signature(
        parent: &Certificate,
        tbs_der: &[u8],
        signature: &[u8],
    ) -> Result<(), SignError> {
        use rsa::pkcs8::DecodePublicKey;
        use signature::Verifier;

        let spki_der = parent
            .tbs_certificate
            .subject_public_key_info
            .to_der()
            .map_err(|e| SignError::DerError(format!("parent RSA SPKI encode: {e}")))?;
        let public_key = rsa::RsaPublicKey::from_public_key_der(&spki_der)
            .map_err(|e| SignError::DerError(format!("parent RSA public key parse: {e}")))?;
        let signature = rsa::pkcs1v15::Signature::try_from(signature)
            .map_err(|e| SignError::DerError(format!("RSA PKCS1 signature parse: {e}")))?;
        let verifier = rsa::pkcs1v15::VerifyingKey::<sha2::Sha256>::new(public_key);
        verifier.verify(tbs_der, &signature).map_err(|e| {
            SignError::DerError(format!("verify certificate chain signature failed: {e}"))
        })
    }

    fn verify_rsa_pkcs1_sha384_certificate_signature(
        parent: &Certificate,
        tbs_der: &[u8],
        signature: &[u8],
    ) -> Result<(), SignError> {
        use rsa::pkcs8::DecodePublicKey;
        use signature::Verifier;

        let spki_der = parent
            .tbs_certificate
            .subject_public_key_info
            .to_der()
            .map_err(|e| SignError::DerError(format!("parent RSA SPKI encode: {e}")))?;
        let public_key = rsa::RsaPublicKey::from_public_key_der(&spki_der)
            .map_err(|e| SignError::DerError(format!("parent RSA public key parse: {e}")))?;
        let signature = rsa::pkcs1v15::Signature::try_from(signature)
            .map_err(|e| SignError::DerError(format!("RSA PKCS1 signature parse: {e}")))?;
        let verifier = rsa::pkcs1v15::VerifyingKey::<sha2::Sha384>::new(public_key);
        verifier.verify(tbs_der, &signature).map_err(|e| {
            SignError::DerError(format!("verify certificate chain signature failed: {e}"))
        })
    }

    fn verify_rsa_pkcs1_sha512_certificate_signature(
        parent: &Certificate,
        tbs_der: &[u8],
        signature: &[u8],
    ) -> Result<(), SignError> {
        use rsa::pkcs8::DecodePublicKey;
        use signature::Verifier;

        let spki_der = parent
            .tbs_certificate
            .subject_public_key_info
            .to_der()
            .map_err(|e| SignError::DerError(format!("parent RSA SPKI encode: {e}")))?;
        let public_key = rsa::RsaPublicKey::from_public_key_der(&spki_der)
            .map_err(|e| SignError::DerError(format!("parent RSA public key parse: {e}")))?;
        let signature = rsa::pkcs1v15::Signature::try_from(signature)
            .map_err(|e| SignError::DerError(format!("RSA PKCS1 signature parse: {e}")))?;
        let verifier = rsa::pkcs1v15::VerifyingKey::<sha2::Sha512>::new(public_key);
        verifier.verify(tbs_der, &signature).map_err(|e| {
            SignError::DerError(format!("verify certificate chain signature failed: {e}"))
        })
    }

    fn certificate_issuer_der(cert_der: &[u8]) -> Result<Vec<u8>, SignError> {
        let cert = Certificate::from_der(cert_der)
            .map_err(|e| SignError::DerError(format!("certificate parse: {e}")))?;
        cert.tbs_certificate
            .issuer
            .to_der()
            .map_err(|e| SignError::DerError(format!("issuer encode: {e}")))
    }

    fn certificate_subject_der(cert_der: &[u8]) -> Result<Vec<u8>, SignError> {
        let cert = Certificate::from_der(cert_der)
            .map_err(|e| SignError::DerError(format!("certificate parse: {e}")))?;
        cert.tbs_certificate
            .subject
            .to_der()
            .map_err(|e| SignError::DerError(format!("subject encode: {e}")))
    }

    // -----------------------------------------------------------------------
    // Modern path: PBES2 + PBKDF2 + AES-256-CBC (DevEco Studio default)
    // -----------------------------------------------------------------------

    fn from_pkcs12_pbes2(
        p12_bytes: &[u8],
        store_password: &str,
        key_password: &str,
    ) -> Result<Self, SignError> {
        use cms::encrypted_data::EncryptedData;
        use const_oid::ObjectIdentifier;
        use der::asn1::{ContextSpecific, OctetString};
        use der::{Decode, Encode};
        use pkcs12::authenticated_safe::AuthenticatedSafe;
        use pkcs12::cert_type::CertBag;
        use pkcs12::pfx::Pfx;
        use pkcs12::safe_bag::SafeContents;
        use pkcs8::EncryptedPrivateKeyInfo;

        // CMS content-type OIDs (RFC 5652).
        const ID_DATA: ObjectIdentifier = ObjectIdentifier::new_unwrap("1.2.840.113549.1.7.1");
        const ID_ENCRYPTED_DATA: ObjectIdentifier =
            ObjectIdentifier::new_unwrap("1.2.840.113549.1.7.6");

        // ── 1. Parse PFX ────────────────────────────────────────────────────
        let pfx = Pfx::from_der(p12_bytes)
            .map_err(|e| SignError::KeystoreParseError(format!("PFX DER parse: {e}")))?;

        // ── 2. Unwrap AuthenticatedSafe ──────────────────────────────────────
        // auth_safe.content is Any, which encodes as an OCTET STRING wrapping
        // the DER-encoded AuthenticatedSafe (SEQUENCE OF ContentInfo).
        let content_der = pfx
            .auth_safe
            .content
            .to_der()
            .map_err(|e| SignError::KeystoreParseError(format!("auth_safe to_der: {e}")))?;
        let auth_safe_os = OctetString::from_der(&content_der)
            .map_err(|e| SignError::KeystoreParseError(format!("auth_safe OctetString: {e}")))?;
        let auth_safes = AuthenticatedSafe::from_der(auth_safe_os.as_bytes())
            .map_err(|e| SignError::KeystoreParseError(format!("AuthenticatedSafe: {e}")))?;

        // ── 3. Walk ContentInfos ────────────────────────────────────────────
        let mut private_key_der: Option<Vec<u8>> = None;
        let mut cert_chain: Vec<Vec<u8>> = Vec::new();

        for content_info in &auth_safes {
            let safe_contents_bytes: Vec<u8>;

            if content_info.content_type == ID_DATA {
                // Plain safe bag — content is OCTET STRING(SafeContents)
                let os_der = content_info.content.to_der().map_err(|e| {
                    SignError::KeystoreParseError(format!("plain safe to_der: {e}"))
                })?;
                let os = OctetString::from_der(&os_der).map_err(|e| {
                    SignError::KeystoreParseError(format!("plain safe OctetString: {e}"))
                })?;
                safe_contents_bytes = os.as_bytes().to_vec();
            } else if content_info.content_type == ID_ENCRYPTED_DATA {
                // Encrypted safe bag — decrypt with PBES2 then parse SafeContents.
                let enc_der = content_info
                    .content
                    .to_der()
                    .map_err(|e| SignError::KeystoreParseError(format!("enc safe to_der: {e}")))?;
                let enc_data = EncryptedData::from_der(&enc_der).map_err(|e| {
                    SignError::KeystoreParseError(format!("EncryptedData parse: {e}"))
                })?;

                let params_der = enc_data
                    .enc_content_info
                    .content_enc_alg
                    .parameters
                    .as_ref()
                    .ok_or_else(|| {
                        SignError::KeystoreParseError("missing PBES2 parameters".into())
                    })?
                    .to_der()
                    .map_err(|e| {
                        SignError::KeystoreParseError(format!("PBES2 params to_der: {e}"))
                    })?;

                let enc_os = enc_data.enc_content_info.encrypted_content.ok_or_else(|| {
                    SignError::KeystoreParseError("missing encrypted content".into())
                })?;

                let original_ct = enc_os.as_bytes().to_vec();

                // Try store_password first; retry with key_password on failure.
                let decrypted = Self::pbes2_decrypt(&params_der, store_password, &original_ct)
                    .or_else(|_| Self::pbes2_decrypt(&params_der, key_password, &original_ct))
                    .map_err(|e| {
                        SignError::KeystoreParseError(format!("PBES2 decrypt (safe): {e}"))
                    })?;

                safe_contents_bytes = decrypted;
            } else {
                // Skip envelope types we don't handle.
                continue;
            }

            // ── 4. Parse SafeContents and collect key + certs ───────────────
            let safe_bags = SafeContents::from_der(&safe_contents_bytes)
                .map_err(|e| SignError::KeystoreParseError(format!("SafeContents parse: {e}")))?;

            for bag in safe_bags {
                match bag.bag_id {
                    pkcs12::PKCS_12_PKCS8_KEY_BAG_OID => {
                        // ShroudedKeyBag → [0] EXPLICIT EncryptedPrivateKeyInfo
                        let cs: ContextSpecific<EncryptedPrivateKeyInfo<'_>> =
                            ContextSpecific::from_der(&bag.bag_value).map_err(|e| {
                                SignError::KeystoreParseError(format!(
                                    "shrouded key bag parse: {e}"
                                ))
                            })?;
                        let mut ct = cs.value.encrypted_data.to_vec();
                        let pt = cs
                            .value
                            .encryption_algorithm
                            .decrypt_in_place(key_password, &mut ct)
                            .map_err(|e| {
                                SignError::KeystoreParseError(format!("key decrypt: {e}"))
                            })?;
                        if private_key_der.is_none() {
                            private_key_der = Some(pt.to_vec());
                        }
                    }
                    pkcs12::PKCS_12_KEY_BAG_OID => {
                        // Plain (unencrypted) PKCS#8 KeyBag
                        use pkcs12::safe_bag::PrivateKeyInfo;
                        let cs: ContextSpecific<PrivateKeyInfo> =
                            ContextSpecific::from_der(&bag.bag_value).map_err(|e| {
                                SignError::KeystoreParseError(format!("key bag parse: {e}"))
                            })?;
                        if private_key_der.is_none() {
                            let der = cs.value.to_der().map_err(|e| {
                                SignError::KeystoreParseError(format!("PrivateKeyInfo to_der: {e}"))
                            })?;
                            private_key_der = Some(der);
                        }
                    }
                    pkcs12::PKCS_12_CERT_BAG_OID => {
                        // CertBag → [0] EXPLICIT CertBag
                        let cs: ContextSpecific<CertBag> =
                            ContextSpecific::from_der(&bag.bag_value).map_err(|e| {
                                SignError::KeystoreParseError(format!("cert bag parse: {e}"))
                            })?;
                        cert_chain.push(cs.value.cert_value.as_bytes().to_vec());
                    }
                    _ => {} // skip unknown bag types
                }
            }
        }

        let private_key_der = private_key_der.ok_or(SignError::NoPrivateKey)?;
        if cert_chain.is_empty() {
            return Err(SignError::NoCertificate);
        }

        Ok(SigningKey {
            private_key_der,
            cert_chain,
        })
    }

    /// Decrypt a PBES2-encrypted blob using the algorithm identified in
    /// `params_der` (DER-encoded `AlgorithmIdentifier` parameters) and the
    /// given password.  Returns the plaintext as a new `Vec<u8>`.
    fn pbes2_decrypt(
        params_der: &[u8],
        password: &str,
        ciphertext: &[u8],
    ) -> Result<Vec<u8>, String> {
        use der::Decode;
        use pkcs5::EncryptionScheme;
        use pkcs8::pkcs5::pbes2;

        let params = pbes2::Parameters::from_der(params_der)
            .map_err(|e| format!("PBES2 params parse: {e}"))?;
        let scheme = EncryptionScheme::from(params);
        let mut ct = ciphertext.to_vec();
        let pt = scheme
            .decrypt_in_place(password, &mut ct)
            .map_err(|e| format!("decrypt_in_place: {e}"))?;
        Ok(pt.to_vec())
    }

    // -----------------------------------------------------------------------
    // Legacy path: 3DES / RC2 (via the `p12` crate)
    // -----------------------------------------------------------------------

    fn from_pkcs12_legacy(p12_bytes: &[u8], key_password: &str) -> Result<Self, SignError> {
        use p12::PFX;

        let pfx = PFX::parse(p12_bytes)
            .map_err(|e| SignError::KeystoreParseError(format!("legacy PKCS#12 parse: {e:?}")))?;

        let keys = pfx
            .key_bags(key_password)
            .map_err(|e| SignError::KeystoreParseError(format!("key bags: {e:?}")))?;
        if keys.is_empty() {
            return Err(SignError::NoPrivateKey);
        }
        let private_key_der = keys.into_iter().next().unwrap();

        let certs = pfx
            .cert_x509_bags(key_password)
            .map_err(|e| SignError::KeystoreParseError(format!("cert bags: {e:?}")))?;
        if certs.is_empty() {
            return Err(SignError::NoCertificate);
        }

        Ok(SigningKey {
            private_key_der,
            cert_chain: certs,
        })
    }

    // -----------------------------------------------------------------------
    // PEM path
    // -----------------------------------------------------------------------

    /// Load from a separate PEM private key + PEM certificate.
    ///
    /// The PEM private key must be PKCS#8 (`BEGIN PRIVATE KEY`) format.
    /// The PEM certificate must be X.509 (`BEGIN CERTIFICATE`) format.
    pub fn from_pem(private_key_pem: &str, cert_pem: &str) -> Result<Self, SignError> {
        let private_key_der = Self::pkcs8_der_from_pem(private_key_pem)?;
        let cert_der = Self::cert_der_from_pem(cert_pem)?;

        Ok(SigningKey {
            private_key_der,
            cert_chain: vec![cert_der],
        })
    }

    /// Extract PKCS#8 DER bytes from a PEM-encoded private key string.
    fn pkcs8_der_from_pem(pem: &str) -> Result<Vec<u8>, SignError> {
        let pem = pem.trim();
        let b64 = pem
            .lines()
            .filter(|l| !l.starts_with("-----"))
            .collect::<Vec<_>>()
            .join("");
        base64_decode(&b64).map_err(|e| SignError::PemError(format!("base64 decode: {e}")))
    }

    /// Extract DER bytes from a PEM-encoded certificate string.
    fn cert_der_from_pem(pem: &str) -> Result<Vec<u8>, SignError> {
        let pem = pem.trim();
        let b64 = pem
            .lines()
            .filter(|l| !l.starts_with("-----"))
            .collect::<Vec<_>>()
            .join("");
        base64_decode(&b64).map_err(|e| SignError::PemError(format!("base64 decode: {e}")))
    }
}

