    /// ```bash
    /// openssl req -x509 -newkey rsa:2048 -keyout /tmp/key.pem -out /tmp/cert.pem \
    ///     -days 3650 -nodes -subj '/CN=test'
    /// openssl pkcs12 -export -out crates/arkdown-sign/tests/fixtures/test.p12 \
    ///     -inkey /tmp/key.pem -in /tmp/cert.pem -passout pass:test123
    /// ```
    #[test]
    fn test_load_rsa_p12_fixture() {
        let p12_path =
            std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/test.p12");
        if !p12_path.exists() {
            tracing::error!("SKIP: test P12 fixture not found at {:?}", p12_path);
            return;
        }
        let p12_bytes = std::fs::read(&p12_path).expect("read test.p12");
        let result = SigningKey::from_pkcs12(&p12_bytes, "test123", "1", "test123");
        assert!(
            result.is_ok(),
            "loading valid RSA P12 with correct password must succeed: {:?}",
            result.err()
        );
        let key = result.unwrap();
        assert!(
            !key.private_key_der.is_empty(),
            "private key DER must not be empty"
        );
        assert!(
            !key.cert_chain.is_empty(),
            "certificate chain must not be empty"
        );
        assert!(
            !key.cert_chain[0].is_empty(),
            "leaf certificate DER must not be empty"
        );
    }

    #[test]
    fn test_cert_chain_from_pem_file_uses_app_cert_file_contents() {
        use base64::Engine;

        let p12_path =
            std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/test.p12");
        if !p12_path.exists() {
            tracing::error!("SKIP: test P12 fixture not found at {:?}", p12_path);
            return;
        }
        let p12_bytes = std::fs::read(&p12_path).expect("read test.p12");
        let key = SigningKey::from_pkcs12(&p12_bytes, "test123", "1", "test123")
            .expect("load fixture p12");
        let cert = key.cert_chain.first().expect("fixture cert");
        let pem = format!(
            "-----BEGIN CERTIFICATE-----\n{}\n-----END CERTIFICATE-----\n",
            base64::engine::general_purpose::STANDARD.encode(cert)
        );
        let temp_dir = tempfile::tempdir().expect("tempdir");
        let cert_path = temp_dir.path().join("app.cer");
        std::fs::write(&cert_path, pem).expect("write app cert");

        let cert_chain =
            SigningKey::cert_chain_from_file(&cert_path).expect("read appCertFile cert chain");

        assert_eq!(cert_chain, vec![cert.clone()]);
    }

